dataTableFormat:
{
    "data convert": [
        {
            "type": "join",
            "field name": "Reference",
            "fields to join": [
                "Title",
                "Citation"
            ],
            "join by": ". "
        },
        {
            "type": "raw",
            "field name": "Effector list name",
            "raw field": "Effector list name"
        },
        {
            "type": "raw",
            "field name": "Trait",
            "raw field": "Trait"
        },
        {
            "type": "raw",
            "field name": "Phenotype group",
            "raw field": "Phenotype group"
        },
        {
            "type": "raw",
            "field name": "PMID",
            "raw field": "PMID"
        },
        {
            "type": "raw",
            "field name": "Effector Gene List",
            "raw field": "Page ID"
        },
        {
            "type": "raw",
            "field name": "Curated vs automated",
            "raw field": "Curated vs automated"
        } ,   
        {
            "type": "raw",
            "field name": "Top gene vs multiple genes per locus",
            "raw field": "Top gene vs multiple genes per locus"
        } ,   
        {
            "type": "raw",
            "field name": "Scoring system",
            "raw field": "Scoring system"
        }    
    ],
    "top rows": [
        "Effector list name",
        "Trait",
        "Phenotype group",
        "Reference",
        "PMID",
        "Effector Gene List"
    ],
    "column formatting": {
        "Effector Gene List": {
            "type": ["link"],
            "link to": "/research.html?pageid=",
            "new tab": "true",
            "link type": "button",
            "link label": "Go to list"
        },
        "PMID": {
            "type": ["link"],
            "link to": "https://pubmed.ncbi.nlm.nih.gov/",
            "new tab": "true"
        }
    },
    "features": [
        "List type"
    ],
    "List type": [
        "Curated vs automated",	
        "Top gene vs multiple genes per locus",		
        "Scoring system"
    ]
}

